CREATE DATABASE IF NOT EXISTS dom_dela CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dom_dela;
CREATE TABLE families (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, invite_code VARCHAR(20) NOT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('adult','child') NOT NULL, avatar VARCHAR(8) NOT NULL DEFAULT 'Д', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE family_members (family_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL UNIQUE, joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (family_id,user_id), FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE join_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, status ENUM('pending','accepted','rejected') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, creator_id BIGINT UNSIGNED NOT NULL, title VARCHAR(120) NOT NULL, description TEXT NOT NULL, category VARCHAR(50) NOT NULL, task_date DATE NOT NULL, task_time TIME NOT NULL, deadline DATETIME NOT NULL, priority ENUM('low','normal','high') NOT NULL DEFAULT 'normal', urgent BOOLEAN NOT NULL DEFAULT FALSE, base_points SMALLINT UNSIGNED NOT NULL DEFAULT 10, assignee_mode ENUM('members','all','open') NOT NULL, status ENUM('active','reserved','doing','done','archived') NOT NULL DEFAULT 'active', started_at DATETIME NULL, started_by BIGINT UNSIGNED NULL, completed_at DATETIME NULL, completed_by BIGINT UNSIGNED NULL, duration_minutes INT UNSIGNED NULL, parent_id BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (creator_id) REFERENCES users(id), FOREIGN KEY (started_by) REFERENCES users(id), FOREIGN KEY (completed_by) REFERENCES users(id), INDEX (family_id,task_date));
CREATE TABLE task_assignments (task_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (task_id,user_id), FOREIGN KEY (task_id) REFERENCES tasks(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE task_reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, task_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, reserved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, ended_at DATETIME NULL, outcome ENUM('active','completed','expired','released') NOT NULL DEFAULT 'active', FOREIGN KEY (task_id) REFERENCES tasks(id), FOREIGN KEY (user_id) REFERENCES users(id), INDEX (task_id,outcome));
CREATE TABLE task_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, task_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NULL, event_type VARCHAR(40) NOT NULL, body VARCHAR(500) NOT NULL, archived BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (task_id) REFERENCES tasks(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE task_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, task_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (task_id) REFERENCES tasks(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE recurring_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, task_id BIGINT UNSIGNED NOT NULL, frequency ENUM('daily','weekly','weekdays','custom') NOT NULL, week_days VARCHAR(20) NULL, next_date DATE NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY (task_id) REFERENCES tasks(id));
CREATE TABLE duty_rotations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, recurring_task_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, position SMALLINT UNSIGNED NOT NULL, FOREIGN KEY (recurring_task_id) REFERENCES recurring_tasks(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE points_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, task_id BIGINT UNSIGNED NOT NULL, points INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (task_id) REFERENCES tasks(id));
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, creator_id BIGINT UNSIGNED NOT NULL, member_id BIGINT UNSIGNED NULL, title VARCHAR(120) NOT NULL, event_date DATE NOT NULL, event_time TIME NOT NULL, event_type ENUM('birthday','meeting','walk','trip','other') NOT NULL, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (creator_id) REFERENCES users(id), FOREIGN KEY (member_id) REFERENCES users(id));
CREATE TABLE messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, task_id BIGINT UNSIGNED NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (task_id) REFERENCES tasks(id));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, type VARCHAR(40) NOT NULL, body VARCHAR(500) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE achievements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, code VARCHAR(50) NOT NULL, achieved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (user_id,code), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE family_state (family_id BIGINT UNSIGNED PRIMARY KEY, mood ENUM('good','calm','tense','conflict','hard','recovery') NOT NULL DEFAULT 'calm', updated_by BIGINT UNSIGNED NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id), FOREIGN KEY (updated_by) REFERENCES users(id));
CREATE TABLE house_progress (family_id BIGINT UNSIGNED PRIMARY KEY, completed_tasks INT UNSIGNED NOT NULL DEFAULT 0, garden_level SMALLINT UNSIGNED NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families(id));
